from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(data, j, j + 1):
                    self.swap(data, j, j + 1)

    @abstractmethod
    def compare(self, data, index1, index2):
        pass

    @abstractmethod
    def swap(self, data, index1, index2):
        pass

class BubbleSort(SortAlgorithm):
    def compare(self, data, index1, index2):
        return data[index1] > data[index2]  # Bubble sort swaps if left is greater than right

    def swap(self, data, index1, index2):
        data[index1], data[index2] = data[index2], data[index1]

class SelectionSort(SortAlgorithm):
    def compare(self, data, index1, index2):
        # In selection sort, comparison is between current minimum and current element
        return data[index1] > data[index2]

    def swap(self, data, index1, index2):
        data[index1], data[index2] = data[index2], data[index1]

    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(data, min_idx, j):
                    min_idx = j
            self.swap(data, i, min_idx)

